# -*- coding: utf-8 -*-
"""Fable 5.2 showcase film. Everything (picture + sound) is generated by this file.
usage:
  python fable.py stills 2.0 8.0 ...   -> stills/still_XXXX.png
  python fable.py frames               -> frames/f_00000.png ...
  python fable.py audio                -> audio.wav
  python fable.py mux out.mp4
"""
import sys, os, math, wave, subprocess
import numpy as np
from PIL import Image, ImageDraw, ImageFont

W, H = 1920, 1080
FPS = 30
DUR = 40.0
NX, NZ = 450, 200
N = NX * NZ  # 90,000 particles
SUB = 3      # motion-blur sub frames
ZC = 3.2     # camera distance
HERE = os.path.dirname(os.path.abspath(__file__))

FONT_JP = r"C:\Windows\Fonts\NotoSansJP-VF.ttf"
FONT_EN = r"C:\Windows\Fonts\bahnschrift.ttf"
PROMPT = "> Fable 5.2 の魅力を最大限発揮するような動画作成して。"
TYPE_T0, TYPE_DUR = 0.7, 3.0
HITS = [6.0, 16.0, 20.0, 24.0, 28.0, 32.0]

INDIGO = np.array([0.28, 0.36, 1.0], np.float32)
CYAN = np.array([0.25, 0.80, 1.0], np.float32)
GOLD = np.array([1.0, 0.72, 0.30], np.float32)
WARM = np.array([1.0, 0.94, 0.84], np.float32)
PINK = np.array([1.0, 0.45, 0.50], np.float32)


def font(size, weight=500, path=FONT_JP):
    f = ImageFont.truetype(path, size)
    try:
        f.set_variation_by_axes([weight] if path == FONT_JP else [weight, 100])
    except Exception:
        pass
    return f


_mask_cache = {}


def text_mask(text, size, weight, cx, cy, tracking=0, path=FONT_JP):
    key = (text, size, weight, cx, cy, tracking, path)
    if key in _mask_cache:
        return _mask_cache[key]
    f = font(size, weight, path)
    img = Image.new("L", (W, H), 0)
    d = ImageDraw.Draw(img)
    if tracking == 0:
        d.text((cx, cy), text, font=f, fill=255, anchor="mm")
    else:
        ws = [f.getlength(ch) for ch in text]
        x = cx - (sum(ws) + tracking * (len(text) - 1)) / 2
        for ch, w in zip(text, ws):
            d.text((x, cy), ch, font=f, fill=255, anchor="lm")
            x += w + tracking
    m = np.asarray(img, dtype=np.float32) / 255.0
    _mask_cache[key] = m
    return m


def prompt_layout():
    f = font(50, 500)
    total = f.getlength(PROMPT)
    x0 = (W - total) / 2
    cuts = [x0 + f.getlength(PROMPT[:i]) for i in range(len(PROMPT) + 1)]
    return f, x0, cuts


def prompt_mask():
    key = "prompt"
    if key not in _mask_cache:
        f, x0, _ = prompt_layout()
        img = Image.new("L", (W, H), 0)
        ImageDraw.Draw(img).text((x0, 540), PROMPT, font=f, fill=255, anchor="lm")
        _mask_cache[key] = np.asarray(img, dtype=np.float32) / 255.0
    return _mask_cache[key]


def logo_mask():
    return text_mask("Fable 5.2", 300, 700, 960, 450, 0, FONT_EN)


# ---------------------------------------------------------------- shapes
def sample(dens, col, rng, zs=0.02):
    p = dens.ravel().astype(np.float64)
    p /= p.sum()
    idx = rng.choice(p.size, N, p=p)
    py, px = idx // W, idx % W
    x = (px + rng.random(N) - 960) / 540
    y = (py + rng.random(N) - 540) / 540
    z = rng.normal(0, zs, N)
    if col.ndim == 3:
        c = col.reshape(-1, 3)[idx]
    else:
        c = np.tile(col, (N, 1))
    return np.stack([x, y, z], 1).astype(np.float32), c.astype(np.float32)


def draw_blueprint():
    img = Image.new("L", (W, H), 0)
    d = ImageDraw.Draw(img)
    for x in range(360, 1561, 60):
        d.line([(x, 150), (x, 840)], fill=20, width=1)
    for y in range(150, 841, 60):
        d.line([(360, y), (1560, y)], fill=20, width=1)

    def iso(x, y, z, cx=730, cy=545, s=62):
        return (cx + (x - y) * 0.866 * s, cy + (x + y) * 0.5 * s - z * s)

    def box(x0, y0, z0, dx, dy, dz):
        P = [(x0 + a * dx, y0 + b * dy, z0 + c * dz) for a in (0, 1) for b in (0, 1) for c in (0, 1)]
        for i in range(8):
            for j in range(i + 1, 8):
                if sum(P[i][k] != P[j][k] for k in range(3)) == 1:
                    d.line([iso(*P[i]), iso(*P[j])], fill=255, width=3)

    box(0, 0, 0, 4, 4, 1)
    box(0.5, 0.5, 1, 3, 3, 2)
    box(1, 1, 3, 2, 2, 2.5)
    d.line([iso(2, 2, 5.5), iso(2, 2, 7)], fill=255, width=3)
    d.line([(430, 235), (430, 795)], fill=170, width=2)
    for y in (235, 795):
        d.line([(415, y), (445, y)], fill=170, width=2)
    d.text((395, 515), "H 7.0", font=font(22, 400, FONT_EN), fill=200, anchor="rm")
    cx, cy = 1265, 420
    for r, wd in ((175, 3), (115, 2), (32, 3)):
        d.ellipse([cx - r, cy - r, cx + r, cy + r], outline=255, width=wd)
    d.line([(cx - 215, cy), (cx + 215, cy)], fill=130, width=1)
    d.line([(cx, cy - 215), (cx, cy + 215)], fill=130, width=1)
    for k in range(12):
        a = k * math.pi / 6 + 0.26
        d.line([(cx + 115 * math.cos(a), cy + 115 * math.sin(a)),
                (cx + 175 * math.cos(a), cy + 175 * math.sin(a))], fill=255, width=3)
    d.rectangle([1050, 690, 1500, 800], outline=255, width=2)
    d.line([(1050, 745), (1500, 745)], fill=200, width=1)
    d.line([(1330, 745), (1330, 800)], fill=200, width=1)
    d.text((1070, 718), "FABLE 5.2", font=font(32, 700, FONT_EN), fill=255, anchor="lm")
    d.text((1070, 773), "PLAN  A-01", font=font(22, 400, FONT_EN), fill=220, anchor="lm")
    d.text((1350, 773), "1 : 100", font=font(22, 400, FONT_EN), fill=220, anchor="lm")
    return np.asarray(img, np.float32) / 255.0


def draw_graph():
    img = Image.new("L", (W, H), 0)
    ln = Image.new("L", (W, H), 0)
    d, dl = ImageDraw.Draw(img), ImageDraw.Draw(ln)
    d.line([(480, 810), (1460, 810)], fill=255, width=3)
    d.line([(480, 810), (480, 180)], fill=255, width=3)
    for gy in range(250, 800, 112):
        d.line([(484, gy), (1460, gy)], fill=24, width=1)
    pts = []
    for i in range(8):
        h = 50 + 400 * (i / 7) ** 1.7 + (18 if i % 3 == 1 else 0)
        x = 545 + i * 112
        d.rectangle([x, 808 - h, x + 70, 808], fill=70, outline=255, width=3)
        pts.append((x + 35, 808 - h - 95 - 6 * i))
    dl.line(pts, fill=255, width=6, joint="curve")
    for (x, y) in pts:
        dl.ellipse([x - 12, y - 12, x + 12, y + 12], fill=255)
    x, y = pts[-1]
    dl.polygon([(x + 60, y - 42), (x + 22, y - 44), (x + 46, y - 8)], fill=255)
    dl.line([(x, y), (x + 44, y - 30)], fill=255, width=6)
    a, b = np.asarray(img, np.float32) / 255.0, np.asarray(ln, np.float32) / 255.0
    yy = np.mgrid[0:H, 0:W][0].astype(np.float32)
    k = np.clip((810 - yy) / 520, 0, 1)[..., None]
    col = INDIGO * (1 - k) + CYAN * k
    col = np.where(b[..., None] > 0.05, GOLD, col)
    return np.maximum(a, b * 1.3), col.astype(np.float32)


def draw_text():
    lines = ["言葉を受けとり、", "意図を読みとり、", "かたちにして、", "確かめる。"]
    img = Image.new("L", (W, H), 0)
    d = ImageDraw.Draw(img)
    f = font(118, 700)
    for i, s in enumerate(lines):
        d.text((960, 225 + i * 160), s, font=f, fill=255, anchor="mm")
    a = np.asarray(img, np.float32) / 255.0
    yy = np.mgrid[0:H, 0:W][0]
    col = np.where((yy > 625)[..., None], GOLD, WARM).astype(np.float32)
    return a, col


def draw_picture(rng):
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    dens = np.zeros((H, W), np.float32)
    col = np.zeros((H, W, 3), np.float32)
    hz = 640.0
    k = np.clip((yy - 150) / (hz - 150), 0, 1)
    sky = yy < hz
    dens[sky] = (0.04 + 0.10 * k ** 2)[sky]
    skyc = INDIGO * (1 - k[..., None] ** 1.5) + np.array([1.0, 0.45, 0.32], np.float32) * k[..., None] ** 1.5
    col[sky] = skyc[sky]
    sx, sy, sr = 730.0, 400.0, 105.0
    ds = np.hypot(xx - sx, yy - sy)
    halo = sky & (ds >= sr)
    dens[halo] += (0.30 * np.exp(-(ds - sr) / 55))[halo]
    col[halo] = (col * 0.5 + GOLD * 0.5)[halo]
    sun = ds < sr
    dens[sun] = 1.0
    col[sun] = np.array([1.0, 0.82, 0.38], np.float32)
    px = 1040.0
    dx = np.abs(xx - px)
    hgt = np.minimum(360 * np.clip(1 - dx / 540, 0, 1) ** 1.7, 338 + 5 * np.sin(xx / 9))
    ym = hz - hgt
    mt = (yy > ym) & sky & (dx < 540)
    dens[mt] = 0.20
    col[mt] = np.array([0.20, 0.30, 0.80], np.float32)
    edge = mt & (yy < ym + 4)
    dens[edge] = 1.0
    col[edge] = np.array([0.65, 0.85, 1.0], np.float32)
    snow = mt & (yy < 400 + 20 * np.sin(xx / 14) + 12 * np.sin(xx / 5.3))
    dens[snow] = 0.85
    col[snow] = np.array([1.0, 1.0, 1.0], np.float32)
    water = (yy >= hz) & (yy < 840)
    stripe = (np.sin(yy * 0.55) > 0.15)
    dens[water] = (0.10 * stripe)[water]
    col[water] = np.array([0.25, 0.45, 0.95], np.float32)
    my = 2 * hz - yy
    refl_m = water & (my > hz - 360 * np.clip(1 - dx / 540, 0, 1) ** 1.7) & (dx < 540) & stripe
    dens[refl_m] = 0.30
    col[refl_m] = np.array([0.30, 0.40, 0.90], np.float32)
    refl_s = water & (np.abs(xx - sx) < sr * (0.55 + 0.45 * np.sin(yy * 1.7))) & stripe
    dens[refl_s] = 0.85
    col[refl_s] = GOLD
    line = np.abs(yy - hz) < 1.5
    dens[line] = 0.7
    col[line] = WARM
    for _ in range(140):
        x, y = int(rng.uniform(430, 1490)), int(rng.uniform(160, 380))
        if ds[y, x] > sr + 40 and not mt[y, x]:
            dens[y:y + 2, x:x + 2] = 5.0
            col[y:y + 2, x:x + 2] = 1.0
    inside = (xx > 420) & (xx < 1500) & (yy > 150) & (yy < 840)
    dens *= inside
    border = ((np.abs(xx - 420) < 2) | (np.abs(xx - 1500) < 2)) & (yy > 148) & (yy < 842) | \
             ((np.abs(yy - 150) < 2) | (np.abs(yy - 840) < 2)) & (xx > 418) & (xx < 1502)
    dens[border] = 0.6
    col[border] = WARM
    return dens, col


class Shapes:
    def __init__(self):
        rng = np.random.default_rng(52)
        self.r1 = rng.random(N).astype(np.float32)
        self.r2 = rng.random(N).astype(np.float32)
        self.r3 = (rng.random((N, 3)) * 6.283).astype(np.float32)
        self.sgn = np.where(rng.random(N) < 0.8, 1.0, -1.0).astype(np.float32)
        st = {}
        st["prompt"] = sample(prompt_mask(), WARM, rng, 0.004)
        st["point"] = ((rng.normal(0, 0.006, (N, 3))).astype(np.float32), np.tile(WARM, (N, 1)))
        bp = draw_blueprint()
        p, c = sample(bp, CYAN, rng)
        mix = rng.random(N)[:, None].astype(np.float32) * 0.5
        st["blueprint"] = (p, (c * (1 - mix) + np.array([0.75, 0.9, 1.0], np.float32) * mix))
        st["graph"] = sample(*draw_graph(), rng)
        st["text"] = sample(*draw_text(), rng)
        st["picture"] = sample(*draw_picture(rng), rng)
        lm = logo_mask()
        xx = np.mgrid[0:H, 0:W][1].astype(np.float32)
        k = np.clip((xx - 330) / 1260, 0, 1)[..., None]
        st["logo"] = sample(lm, (CYAN * (1 - k) + GOLD * k).astype(np.float32), rng, 0.03)
        self.static = st
        # galaxy params
        self.g_r = (0.04 + 1.45 * rng.random(N) ** 0.75).astype(np.float32)
        arm = rng.integers(0, 3, N)
        self.g_th = (arm * 2.0944 + self.g_r * 3.6 + rng.normal(0, 1, N) * 0.22 / (self.g_r + 0.25)).astype(np.float32)
        self.g_y = (rng.normal(0, 1, N) * 0.035 * (1.6 - self.g_r)).astype(np.float32)
        k = np.clip(self.g_r / 1.3, 0, 1)[:, None]
        gc = (WARM * 0.5 + GOLD * 0.5) * (1 - k) ** 2 + INDIGO * (1 - (1 - k) ** 2)
        pk = (rng.random(N) < 0.12)[:, None]
        self.g_col = np.where(pk, PINK, gc).astype(np.float32)
        # wave grid
        gx, gz = np.meshgrid(np.linspace(-3.4, 3.4, NX), np.linspace(-0.9, 4.6, NZ))
        self.w_x, self.w_z = gx.ravel().astype(np.float32), gz.ravel().astype(np.float32)
        # halo
        self.h_r = (rng.choice([1.12, 1.30, 1.36, 1.55], N, p=[0.2, 0.4, 0.15, 0.25]) + rng.normal(0, 1, N) * 0.012 + (rng.random(N) < 0.22) * rng.normal(0, 0.22, N)).astype(np.float32)
        self.h_th = (rng.random(N) * 6.283).astype(np.float32)
        self.h_y = (rng.normal(0, 0.025, N)).astype(np.float32)
        k = rng.random(N)[:, None].astype(np.float32)
        self.h_col = (INDIGO * (1 - k) + GOLD * k * 0.9 + 0.1).astype(np.float32)

    def get(self, name, t):
        if name in self.static:
            return self.static[name]
        if name == "galaxy":
            th = self.g_th + t * 0.42 / (self.g_r + 0.35)
            X, Z = self.g_r * np.cos(th), self.g_r * np.sin(th)
            a = 1.12
            y = self.g_y * math.cos(a) + Z * math.cos(a)
            z = Z * math.sin(a) - self.g_y * 0.4
            ro = 0.28
            x2 = X * math.cos(ro) - y * math.sin(ro)
            y2 = X * math.sin(ro) + y * math.cos(ro)
            return np.stack([x2, y2 - 0.03, z], 1), self.g_col
        if name == "wave":
            x, z = self.w_x, self.w_z
            h = (0.14 * np.sin(2.0 * x + 1.5 * t) * np.cos(1.6 * z - 1.1 * t)
                 + 0.07 * np.sin(3.3 * x - 2.1 * z + 2.3 * t) + 0.05 * np.sin(5.0 * z + 1.7 * t))
            k = np.clip((h + 0.16) / 0.36, 0, 1)[:, None]
            col = INDIGO * (1 - k) + CYAN * k
            g = np.clip((k - 0.72) / 0.28, 0, 1)
            col = col * (1 - g) + GOLD * 1.6 * g
            return np.stack([x, 0.40 - h, z], 1), col.astype(np.float32)
        if name == "halo":
            th = self.h_th + t * 0.22 / np.maximum(self.h_r, 0.4)
            X, Z = self.h_r * np.cos(th), self.h_r * np.sin(th)
            a = 1.30
            return np.stack([X * 1.12, self.h_y + Z * math.cos(a) - 0.167, Z * math.sin(a)], 1), self.h_col
        raise KeyError(name)


# (start, duration, target, gain, style)
SEQ = [
    (-1.0, 0.1, "prompt", 0.55, "io"),
    (4.4, 1.3, "point", 0.3, "in"),
    (6.0, 2.4, "galaxy", 1.7, "burst"),
    (10.0, 2.4, "wave", 2.6, "io"),
    (15.0, 1.5, "blueprint", 1.5, "io"),
    (19.1, 1.4, "graph", 1.1, "io"),
    (23.1, 1.4, "text", 1.2, "io"),
    (27.1, 1.4, "picture", 1.6, "io"),
    (31.0, 1.5, "logo", 1.0, "io"),
    (34.4, 3.2, "halo", 1.3, "io"),
]


def ease_io(p):
    p = np.clip(p, 0, 1)
    return p * p * p * (p * (p * 6 - 15) + 10)


def state(S, t):
    i = 0
    for k, s in enumerate(SEQ):
        if t >= s[0]:
            i = k
    t0, d, name, gain, style = SEQ[i]
    B, cB = S.get(name, t)
    u = (t - t0) / d
    if i == 0 or u >= 1.0:
        pos, col, g = B.copy(), cB, gain
        swirl = None
    else:
        _, _, pname, pgain, _ = SEQ[i - 1]
        A, cA = S.get(pname, t)
        if style == "burst":
            p = 1 - np.power(2.0, -9 * np.clip(u * (0.75 + 0.5 * S.r1), 0, 1))
            p = np.clip(p / (1 - 2.0 ** -9), 0, 1)
        elif style == "in":
            p = np.clip((u - 0.3 * S.r1) / 0.7, 0, 1) ** 3
        else:
            p = ease_io((u - 0.35 * S.r1) / 0.65)
        p = p.astype(np.float32)
        pos = A + (B - A) * p[:, None]
        col = cA + (cB - cA) * p[:, None]
        g = pgain + (gain - pgain) * float(ease_io(np.float32(u)))
        swirl = np.sin(np.pi * p)
        if style != "in":
            ang = swirl * (0.35 + 0.9 * S.r2) * S.sgn * (0.6 if style == "burst" else 1.0)
            ca, sa = np.cos(ang), np.sin(ang)
            x, y = pos[:, 0].copy(), pos[:, 1].copy()
            pos[:, 0] = x * ca - y * sa
            pos[:, 1] = x * sa + y * ca
            pos[:, 2] -= swirl * (S.r1 - 0.25) * 1.1
            pos += (np.sin(S.r3 + t * 2.0) * (swirl * 0.07)[:, None])
    pos = pos + np.sin(S.r3 + t * 1.6) * 0.0028
    return pos, col, g


def particle_alpha(t):
    a = min(max((t - 4.25) / 0.25, 0.0), 1.0)
    if t > 35.0:
        a *= 1.0 - 0.45 * min((t - 35.0) / 2.5, 1.0)
    return a


def fade(t, a, b, c, d):
    if t <= a or t >= d:
        return 0.0
    if t < b:
        return (t - a) / (b - a)
    if t > c:
        return (d - t) / (d - c)
    return 1.0


LABELS = [(16.0, "設計する", "DESIGN"), (20.0, "分析する", "ANALYZE"), (24.0, "書く", "WRITE"), (28.0, "描く", "DRAW")]


def captions(t):
    out = []
    if t < 4.7:
        _, x0, cuts = prompt_layout()
        n = int(np.clip((t - TYPE_T0) / TYPE_DUR * len(PROMPT), 0, len(PROMPT)))
        if t < TYPE_T0:
            n = 2 if t > 0.25 else 0
        n = max(n, 2 if t > 0.25 else 0)
        a = 1.0 - min(max((t - 4.25) / 0.25, 0), 1)
        xx = np.arange(W, dtype=np.float32)[None, :]
        m = prompt_mask() * (xx < cuts[n] + 0.5)
        out.append((m, WARM, 1.5 * a))
        if (t * 2.2) % 1.0 < 0.55 or (TYPE_T0 < t < TYPE_T0 + TYPE_DUR):
            cur = np.zeros((H, W), np.float32)
            cx = int(cuts[n] + 8)
            cur[510:572, cx:cx + 5] = 1.0
            out.append((cur, GOLD, 2.0 * a * min(t / 0.3, 1.0)))
    a = fade(t, 7.2, 8.0, 9.4, 10.1)
    if a > 0:
        out.append((text_mask("考えが、広がる。", 44, 400, 960, 940, 14), WARM, 1.5 * a))
    a = fade(t, 11.8, 12.6, 14.2, 14.9)
    if a > 0:
        out.append((text_mask("流れになり、", 44, 400, 960, 940, 14), WARM, 1.5 * a))
    for T, jp, en in LABELS:
        a = fade(t, T - 0.05, T + 0.35, T + 2.9, T + 3.3)
        if a > 0:
            out.append((text_mask(jp, 48, 500, 960, 925, 18), WARM, 1.6 * a))
            out.append((text_mask(en, 22, 500, 960, 990, 14, FONT_EN), GOLD, 1.4 * a))
    a = fade(t, 33.4, 35.2, 100, 101)
    if a > 0:
        out.append((logo_mask(), np.array([1.0, 0.98, 0.94], np.float32), 2.2 * a))
    a = fade(t, 36.0, 36.9, 100, 101)
    if a > 0:
        out.append((text_mask("この映像は、音も含めてすべてコードで書きました。", 40, 400, 960, 715, 6), WARM, 1.5 * a))
    a = fade(t, 37.0, 37.8, 100, 101)
    if a > 0:
        out.append((text_mask("素材 0　｜　粒子 90,000　｜　1,200 フレーム", 24, 500, 960, 790, 8), GOLD, 1.3 * a))
    return out


_post = {}


def post_consts():
    if not _post:
        qh, qw, pad = H // 4, W // 4, 48
        fy = np.fft.fftfreq(qh + 2 * pad)[:, None]
        fx = np.fft.rfftfreq(qw + 2 * pad)[None, :]
        f2 = (fx * fx + fy * fy) * (2 * np.pi) ** 2
        tf = sum(wt * np.exp(-0.5 * f2 * s * s) for wt, s in ((0.50, 1.6), (0.32, 7.0), (0.30, 26.0)))
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        r2 = ((xx - W / 2) / (W / 2)) ** 2 + ((yy - H / 2) / (H / 2)) ** 2
        bg = np.array([0.010, 0.013, 0.036], np.float32) * (1.25 - 0.55 * r2)[..., None]
        vig = (1 - 0.22 * np.clip(r2 - 0.25, 0, None))[..., None].astype(np.float32)
        _post.update(tf=tf.astype(np.float32), bg=np.clip(bg, 0, None), vig=vig, pad=pad)
    return _post


def render(S, t, seed=0):
    acc = np.zeros((3, W * H), np.float64)
    pa = particle_alpha(t)
    yaw = 0.11 * math.sin(t * 0.55 + 0.4)
    cy_, sy_ = math.cos(yaw), math.sin(yaw)
    zoom = 1.0
    for T in HITS[1:5]:
        if T - 1 < t < T + 4:
            zoom = 1.0 + 0.012 * (t - T)
    if pa > 0:
        for s in range(SUB):
            ts = t + s / (FPS * SUB)
            pos, col, g = state(S, ts)
            x = pos[:, 0] * cy_ + pos[:, 2] * sy_
            z = -pos[:, 0] * sy_ + pos[:, 2] * cy_
            depth = np.maximum(ZC + z, 0.25)
            sc = ZC / depth * zoom
            sx = 960 + x * 540 * sc
            sy = 540 + pos[:, 1] * 540 * sc
            wgt = (g * pa / SUB) * np.minimum(sc, 3.0) ** 1.5
            x0 = np.floor(sx).astype(np.int64)
            y0 = np.floor(sy).astype(np.int64)
            fx, fy = sx - x0, sy - y0
            for dx, dy, wb in ((0, 0, (1 - fx) * (1 - fy)), (1, 0, fx * (1 - fy)), (0, 1, (1 - fx) * fy), (1, 1, fx * fy)):
                xi, yi = x0 + dx, y0 + dy
                m = (xi >= 0) & (xi < W) & (yi >= 0) & (yi < H)
                idx = yi[m] * W + xi[m]
                ww = (wb * wgt)[m]
                for c in range(3):
                    acc[c] += np.bincount(idx, weights=ww * col[m, c], minlength=W * H)
    img = acc.T.reshape(H, W, 3).astype(np.float32)
    np.minimum(img, 30.0, out=img)
    for mask, color, a in captions(t):
        img += mask[..., None] * (np.asarray(color, np.float32) * a)
    P = post_consts()
    pad = P["pad"]
    q = img.reshape(H // 4, 4, W // 4, 4, 3).mean(axis=(1, 3))
    qp = np.pad(q, ((pad, pad), (pad, pad), (0, 0)))
    bl = np.empty_like(img)
    for c in range(3):
        b = np.fft.irfft2(np.fft.rfft2(qp[..., c]) * P["tf"], s=qp.shape[:2])[pad:-pad, pad:-pad]
        bl[..., c] = np.asarray(Image.fromarray(b.astype(np.float32), "F").resize((W, H), Image.BICUBIC))
    np.maximum(bl, 0, out=bl)
    flash = sum(math.exp(-(t - T) * 5.0) * (0.9 if T in (6.0, 32.0) else 0.45) for T in HITS if t >= T)
    expo = 1.15 * (1 + flash)
    img = img * 0.85 + bl * (1.5 + 1.2 * flash) + P["bg"]
    out = 1 - np.exp(-expo * img)
    out *= P["vig"]
    g = 1.0
    if t < 0.4:
        g = t / 0.4
    if t > 39.0:
        g = max(0.0, (DUR - 0.1 - t) / 0.9)
    out *= g
    rng = np.random.default_rng(1000 + seed)
    out += rng.normal(0, 0.007, (H, W, 1)).astype(np.float32)
    return (np.clip(out, 0, 1) * 255 + 0.5).astype(np.uint8)


_S = None


def _init():
    global _S
    _S = Shapes()


def _job(fi):
    path = os.path.join(HERE, "frames", "f_%05d.png" % fi)
    Image.fromarray(render(_S, fi / FPS, fi)).save(path, compress_level=1)
    return fi


# ---------------------------------------------------------------- audio
def make_audio(path):
    sr = 44100
    n = int(sr * (DUR + 3))
    rng = np.random.default_rng(5)
    dry, wet, padb, bassb = (np.zeros((n, 2)) for _ in range(4))

    def add(buf, sig, t0, gain=1.0, pan=0.0):
        i = int(t0 * sr)
        if i >= n:
            return
        sig = sig[: n - i]
        buf[i:i + len(sig), 0] += sig * gain * (1 - max(pan, 0))
        buf[i:i + len(sig), 1] += sig * gain * (1 + min(pan, 0))

    def mtof(m):
        return 440.0 * 2 ** ((m - 69) / 12)

    def tt(d):
        return np.arange(int(d * sr)) / sr

    def lp(x, k):
        c = np.cumsum(np.concatenate([np.zeros(k), x]))
        return (c[k:] - c[:-k]) / k

    def pluck(f, d, dec, harm=(1, 0.45, 0.2, 0.08)):
        t = tt(d)
        s = sum(a * np.sin(2 * np.pi * f * (k + 1) * t) for k, a in enumerate(harm))
        return s * np.exp(-t / dec) * np.minimum(t / 0.003, 1)

    def padnote(f, d, bright=1.0):
        t = tt(d)
        s = 0
        for det in (0.996, 1.0, 1.004):
            for h in range(1, 8):
                s = s + np.sin(2 * np.pi * f * det * h * t + h * det * 7) / h ** (2.0 - 0.5 * bright)
        env = np.minimum(t / 0.5, 1) * np.minimum((d - t) / 0.6, 1)
        return s * env / 3

    def kick(g=1.0):
        t = tt(0.4)
        ph = 2 * np.pi * np.cumsum(42 + 120 * np.exp(-t * 38)) / sr
        return (np.sin(ph) * np.exp(-t * 7.5) + 0.3 * np.exp(-t * 400) * rng.normal(0, 1, len(t))) * g

    def noise(d):
        return rng.normal(0, 1, int(d * sr))

    def hp(x, k=6):
        return x - lp(x, k)

    def impact(g):
        t = tt(2.2)
        ph = 2 * np.pi * np.cumsum(38 + 60 * np.exp(-t * 9)) / sr
        s = np.sin(ph) * np.exp(-t * 2.2) * 1.2 + lp(noise(2.2), 24) * np.exp(-t * 3.5) * 1.5
        cr = hp(noise(2.2), 3) * np.exp(-t * 2.0) * 0.22
        return s * g, cr * g

    def riser(d, g):
        t = tt(d)
        u = t / d
        nz = hp(noise(d), 10) * u ** 2.5 * 0.5
        sw = np.sin(2 * np.pi * np.cumsum(180 * 2 ** (u * 3.2)) / sr) * u ** 2 * 0.25
        return (nz + sw) * g

    Am, F, C, G = [57, 60, 64], [53, 57, 60], [48, 55, 64], [55, 59, 62]
    bars = [Am, Am, Am, Am, F, C, G, G, Am, F, C, G, Am, F, F, G]
    # act 1: drone + typing
    t = tt(8.5)
    dr = (np.sin(2 * np.pi * 55 * t) + 0.5 * np.sin(2 * np.pi * 82.41 * t + 1) + 0.25 * np.sin(2 * np.pi * 110.3 * t))
    dr *= np.minimum(t / 2.5, 1) * np.clip((8.5 - t) / 2.5, 0, 1) * (0.85 + 0.15 * np.sin(2 * np.pi * 0.4 * t))
    add(padb, dr, 0.0, 0.16)
    for i in range(len(PROMPT)):
        tc = TYPE_T0 + i * TYPE_DUR / len(PROMPT)
        ts_ = tt(0.03)
        cl = (hp(noise(0.03), 4) * 0.6 + np.sin(2 * np.pi * rng.uniform(1700, 2600) * ts_)) * np.exp(-ts_ * 220)
        add(dry, cl, tc, 0.11, rng.uniform(-0.4, 0.4))
        add(wet, cl, tc, 0.05)
    add(dry, riser(1.6, 0.5), 4.4)
    add(wet, riser(1.6, 0.3), 4.4)
    add(dry, riser(2.0, 0.45), 14.0)
    add(wet, riser(2.0, 0.3), 14.0)
    add(dry, riser(2.0, 0.6), 30.0)
    add(wet, riser(2.0, 0.4), 30.0)
    for T in (20.0, 24.0, 28.0):
        add(dry, riser(0.7, 0.3), T - 0.7)
        add(wet, riser(0.7, 0.3), T - 0.7)
    for T in HITS:
        g = {6.0: 0.9, 16.0: 0.9, 32.0: 1.1}.get(T, 0.5)
        a, b = impact(g)
        add(dry, a, T, 0.55)
        add(wet, a, T, 0.25)
        add(dry, b, T, 0.6)
        add(wet, b, T, 0.6)
    # pads / bass / arp per bar (bar = 2 s)
    kicks = []
    for bi, ch in enumerate(bars):
        t0 = bi * 2.0
        if t0 < 6.0:
            continue
        act3 = t0 >= 16.0
        lvl = 1.0 if act3 else 0.35 + 0.65 * (t0 - 6) / 10
        for m in ch:
            add(padb, padnote(mtof(m), 2.5, 1.0 if act3 else 0.5), t0 - 0.1, 0.085 * lvl, 0.3 * (m % 3 - 1))
        add(padb, padnote(mtof(ch[0] + 24), 2.5, 0.6), t0 - 0.1, 0.03 * lvl)
        root = ch[0] - 24 if ch[0] - 24 >= 31 else ch[0] - 12
        if act3:
            for k in range(8):
                b = np.tanh(pluck(mtof(root), 0.24, 0.16, (1, 0.6, 0.3)) * 2.0)
                add(bassb, b, t0 + k * 0.25, 0.26 if k % 2 == 0 else 0.20)
        elif t0 >= 10.0:
            ts_ = tt(2.0)
            add(bassb, np.sin(2 * np.pi * mtof(root) * ts_) * np.minimum(ts_ / 0.1, 1) * np.minimum((2 - ts_) / 0.2, 1), t0, 0.22)
        notes = [ch[0], ch[1], ch[2], ch[0] + 12, ch[1] + 12, ch[2] + 12, ch[0] + 24, ch[2] + 12]
        step = 0.125 if t0 >= 12.0 else 0.25
        for k in range(int(2.0 / step)):
            m = notes[(k * 3 if act3 else k) % len(notes)] + 12
            v = (0.9 if k % 4 == 0 else 0.6) * lvl
            pl = pluck(mtof(m), 0.5, 0.16 if act3 else 0.22, (1, 0.5, 0.3, 0.15) if act3 else (1, 0.3, 0.1))
            add(dry, pl, t0 + k * step, 0.060 * v, 0.6 * (-1) ** k)
            add(wet, pl, t0 + k * step, 0.050 * v, -0.6 * (-1) ** k)
        if t0 >= 12.0:
            for k in range(4):
                tk = t0 + k * 0.5
                if tk >= 31.0:
                    continue
                kicks.append(tk)
                add(dry, kick(), tk, 0.62 if act3 else 0.34)
        if act3:
            for k in range(16):
                tk = t0 + k * 0.125
                ts_ = tt(0.06)
                hh = hp(hp(noise(0.06), 3), 3) * np.exp(-ts_ * (60 if k % 4 == 2 else 140))
                add(dry, hh, tk, (0.10 if k % 4 == 2 else 0.035 * rng.uniform(0.5, 1.2)), 0.25)
            for k in (1, 3):
                ts_ = tt(0.25)
                cp = hp(lp(noise(0.25), 3), 30) * np.exp(-ts_ * 22) * (1 + (ts_ < 0.02))
                add(dry, cp, t0 + k * 0.5, 0.30)
                add(wet, cp, t0 + k * 0.5, 0.20)
    for k in range(8):  # snare roll into the logo
        ts_ = tt(0.1)
        add(dry, hp(lp(noise(0.1), 3), 30) * np.exp(-ts_ * 35), 31.0 + k * 0.125, 0.10 + 0.03 * k)
    # act 4: resolution chord + bells
    for m, g in ((36, 0.0), (48, 0.10), (55, 0.09), (60, 0.09), (64, 0.09), (67, 0.07), (74, 0.05), (76, 0.04)):
        if g:
            add(padb, padnote(mtof(m), 9.5, 1.0), 31.95, g, 0.4 * (m % 3 - 1))
    ts_ = tt(8.0)
    add(bassb, np.sin(2 * np.pi * mtof(36) * ts_) * np.exp(-ts_ / 3.0) * np.minimum(ts_ / 0.02, 1), 32.0, 0.34)
    bell = [72, 76, 79, 84, 86, 88, 91, 96, 91, 88, 96, 100]
    for k, m in enumerate(bell):
        pl = pluck(mtof(m), 2.0, 0.6, (1, 0.25, 0.4, 0.1))
        tk = 32.0 + k * 0.375 + 0.02 * k * k * 0.375
        add(dry, pl, tk, 0.05 * (1 - k / 16), 0.5 * (-1) ** k)
        add(wet, pl, tk, 0.07 * (1 - k / 16), -0.5 * (-1) ** k)
    # sidechain
    duck = np.ones(n)
    tfull = np.arange(n) / sr
    for tk in kicks:
        i = int(tk * sr)
        seg = tfull[i:i + int(0.4 * sr)] - tk
        duck[i:i + len(seg)] = np.minimum(duck[i:i + len(seg)], 1 - 0.55 * np.exp(-seg * 9))
    # reverb
    L = int(2.8 * sr)
    tr = np.arange(L) / sr
    nf = 1 << int(np.ceil(np.log2(n + L)))
    rev = np.zeros((n, 2))
    for c in range(2):
        ir = rng.normal(0, 1, L) * np.exp(-tr / 0.55)
        ir = hp(ir, 40)
        rev[:, c] = np.fft.irfft(np.fft.rfft(wet[:, c], nf) * np.fft.rfft(ir, nf), nf)[:n]
    rev /= np.abs(rev).max() + 1e-9
    mix = dry + (padb + bassb) * duck[:, None] + rev * 0.42
    mix = mix[: int(DUR * sr)]
    tm = np.arange(len(mix)) / sr
    env = np.clip(tm / 0.3, 0, 1) * np.clip((DUR - 0.15 - tm) / 2.6, 0, 1) ** 1.3
    mix = np.tanh(mix * 1.5) * env[:, None]
    mix *= 0.92 / np.abs(mix).max()
    with wave.open(path, "wb") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(sr)
        w.writeframes((mix * 32767).astype("<i2").tobytes())


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "stills":
        os.makedirs(os.path.join(HERE, "stills"), exist_ok=True)
        S = Shapes()
        for a in sys.argv[2:]:
            t = float(a)
            Image.fromarray(render(S, t, int(t * FPS))).save(os.path.join(HERE, "stills", "still_%05.2f.png" % t))
            print("still", t, flush=True)
    elif cmd == "frames":
        from multiprocessing import Pool
        os.makedirs(os.path.join(HERE, "frames"), exist_ok=True)
        total = int(DUR * FPS)
        with Pool(int(sys.argv[2]) if len(sys.argv) > 2 else 12, initializer=_init) as pool:
            for k, fi in enumerate(pool.imap_unordered(_job, range(total), chunksize=4)):
                if k % 100 == 0:
                    print("frame", k, "/", total, flush=True)
    elif cmd == "audio":
        make_audio(os.path.join(HERE, "audio.wav"))
        print("audio ok")
    elif cmd == "mux":
        import imageio_ffmpeg
        ff = imageio_ffmpeg.get_ffmpeg_exe()
        subprocess.check_call([ff, "-y", "-framerate", str(FPS), "-i", os.path.join(HERE, "frames", "f_%05d.png"),
                               "-i", os.path.join(HERE, "audio.wav"), "-c:v", "libx264", "-preset", "slow", "-crf", "16",
                               "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "256k", "-movflags", "+faststart",
                               "-shortest", sys.argv[2]])
